'use strict';
window.WorkOSTaskBoard=(()=>{
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const ico=n=>`<i class="ph ph-${n}" aria-hidden="true"></i>`;
 let ctx={},data=null,error='',pending=false,query='',person='',status='',menu=null,selected=new Set(),expanded=new Set(),viewDirty=false,identity=null,request=0;
 const tr=(zh,en)=>ctx.language==='en'?en:zh,word=x=>x?.[ctx.language==='en'?'en':'zh']||'',name=id=>ctx.directory?.find(u=>u.id===id)?.display_name||id||'—';
 const columns=[['owner','负责人','Owner'],['priority','优先级','Priority'],['status','状态','Status'],['category','分类','Category'],['due','截止日期','Due date'],['notes','备注','Notes'],['updated','最后更新','Last updated']];
 const view=()=>data?.view||{sort:[],groupBy:'group',hidden:[],collapsed:[]};
 const label=(kind,id)=>data?.config?.[kind]?.find(l=>l.id===id);
 const safeColor=c=>/^#[0-9a-f]{6}$/i.test(c)?c:'#797e95';
 const initials=id=>name(id).split(/\s+/).map(s=>s[0]).join('').slice(0,2).toUpperCase();
 const btn=(text,action,icon='',cls='',extra='')=>`<button type="button" class="mb-button ${cls}" data-mb="${action}" ${text?`aria-label="${esc(text)}"`:""} ${extra}>${icon?ico(icon):''}<span>${text}</span></button>`;
 function configure(c){if(identity&&identity!==c.actor?.id)reset();ctx=c;identity=c.actor?.id;}
 function reset(){ctx={};data=null;error='';pending=false;query='';person='';status='';menu=null;selected.clear();expanded.clear();identity=null;request++;}
 async function refresh(){const id=identity,n=++request;try{const next=await ctx.api.get('/task-board');if(id!==identity||n!==request)return;const unsavedView=viewDirty?data?.view:null;data=next;if(unsavedView)data.view=unsavedView;error='';ctx.onTasksChanged?.(data.items);return data;}catch(e){if(id===identity){error=e.message;throw e;}}}
 function redraw(){const root=document.querySelector('[data-task-board-root]');if(!root)return;const input=root.querySelector('[data-mb-search]'),focused=document.activeElement===input,range=input?.selectionStart;root.innerHTML=body();if(focused){const next=root.querySelector('[data-mb-search]');next?.focus();next?.setSelectionRange(range,range);}}
 function render(){return `<section class="monday-board" data-task-board-root>${body()}</section>`;}
 function fieldValue(t,k){if(k==='priority')return data.config.priority.findIndex(l=>l.id===t.board_priority);if(k==='status')return data.config.status.findIndex(l=>l.id===t.board_status);if(k==='due')return new Date(t.due_at).getTime();if(k==='updated')return new Date(t.updated_at||t.created_at).getTime();if(k==='category')return word(label('category',t.board_category));return t.title.toLocaleLowerCase();}
 function sortTasks(items){return items.slice().sort((a,b)=>{for(const s of view().sort){const x=fieldValue(a,s.field),y=fieldValue(b,s.field),v=typeof x==='number'?x-y:String(x).localeCompare(String(y));if(v)return s.direction==='desc'?-v:v;}return String(a.created_at).localeCompare(String(b.created_at))||a.id.localeCompare(b.id);});}
 function matches(t){const q=query.toLocaleLowerCase().trim();return (!q||[t.title,t.board_notes,name(t.owner_id),word(label('category',t.board_category))].join(' ').toLocaleLowerCase().includes(q))&&(!person||t.owner_id===person)&&(!status||t.board_status===status);}
 function grouped(){if(!data)return [];const all=data.items,visible=new Set(all.filter(matches).map(t=>t.id));all.filter(t=>t.parent_task_id&&visible.has(t.id)).forEach(t=>visible.add(t.parent_task_id));const items=all.filter(t=>visible.has(t.id)),roots=items.filter(t=>!t.parent_task_id||!all.some(p=>p.id===t.parent_task_id));const key=t=>view().groupBy==='group'?t.effective_group_id:view().groupBy==='owner'?t.owner_id:view().groupBy==='due'?(t.due_at||'').slice(0,10):t['board_'+view().groupBy];let groups;
  if(view().groupBy==='group')groups=data.config.groups.map(g=>({...g,items:[]}));else if(['status','priority','category'].includes(view().groupBy))groups=[...data.config[view().groupBy],...(view().groupBy==='category'?[{id:'',en:'Uncategorized',zh:'未分类',color:'#797e95'}]:[])].map(g=>({...g,items:[]}));else groups=[];
  for(const t of sortTasks(roots)){let g=groups.find(g=>g.id===key(t));if(!g){g={id:key(t)||'unassigned',en:view().groupBy==='owner'?name(key(t)):key(t),zh:view().groupBy==='owner'?name(key(t)):key(t),color:'#579bfc',items:[]};groups.push(g);}g.items.push(t);}
  return groups.filter(g=>view().groupBy==='group'||g.items.length).map(g=>({...g,children:items.filter(t=>t.parent_task_id)}));
 }
 function body(){return `<header class="mb-heading"><div><h1>${ico('table')} ${tr('任务看板','Task board')}</h1><p>${tr('团队任务、负责人和进度，一处查看。','A shared view of tasks, owners and progress.')}</p></div><div class="mb-heading-actions">${btn(tr('刷新','Refresh'),'refresh','arrows-clockwise')}${btn(tr('看板设置','Board settings'),'settings','gear-six')}</div></header><div class="mb-tabs"><button class="mb-tab active">${ico('table')}${tr('主表格','Main table')}</button><span class="mb-board-scope">${esc(ctx.actor?.display_name)} · ${tr('授权任务','Authorized tasks')}</span></div>${error?`<p class="mb-alert" role="alert">${esc(error)}</p>`:''}${data?toolbar()+groupsHTML()+footer()+popover():`<div class="mb-loading" role="status">${esc(error||tr('正在读取任务看板…','Loading your task board…'))}${btn(tr('重试','Retry'),'refresh','arrows-clockwise')}</div>`}`;}
 function toolbar(){const total=data.items.filter(matches).length;return `<div class="mb-toolbar">${btn(tr('新建任务','New task'),'new','plus','mb-new')}<label class="mb-search">${ico('magnifying-glass')}<input type="search" data-mb-search aria-label="${tr('搜索任务','Search tasks')}" placeholder="${tr('搜索','Search')}" value="${esc(query)}"></label>${btn(tr('人员','Person')+(person?' / 1':''),'person','user-circle',person?'mb-active':'')}${btn(tr('筛选','Filter')+(status?' / 1':''),'filter','funnel',status?'mb-active':'')}${btn(tr('排序','Sort')+' / '+view().sort.length,'sort','arrows-down-up',view().sort.length?'mb-active':'')}${btn(tr('隐藏','Hide')+(view().hidden.length?' / '+view().hidden.length:''),'hide','eye-slash')}${btn(tr('分组依据','Group by')+(view().groupBy!=='group'?' / 1':''),'groupBy','columns',view().groupBy!=='group'?'mb-active':'')}${btn(tr('添加分组','Add group'),'add-group','plus')}<span class="mb-count">${total} ${tr('项','items')}</span>${selected.size?`<div class="mb-selection"><strong>${selected.size} ${tr('已选','selected')}</strong>${btn(tr('批量状态','Set status'),'batch-status','check-square')}${btn(tr('移至分组','Move to group'),'batch-group','folder-simple')}${btn(tr('清除','Clear'),'clear-selection','x')}</div>`:''}</div>`;}
 function visibleCols(){return columns.filter(([id])=>!view().hidden.includes(id));}
 function head(sub=false){return `<tr class="mb-column-head"><th class="mb-check"><input type="checkbox" data-mb-select-group aria-label="${tr('选择本组任务','Select tasks in this group')}"></th><th class="mb-task-head">${tr(sub?'子任务':'任务',sub?'Subitem':'Task')}</th>${visibleCols().map(([id,zh,en])=>`<th class="mb-col-${id}"><button data-mb="column-sort" data-field="${id==='due'?'due':id==='updated'?'updated':id}" ${id==='owner'||id==='notes'?'disabled':''}>${tr(zh,en)}${view().sort.some(s=>s.field===id)?ico(view().sort.find(s=>s.field===id).direction==='asc'?'arrow-up':'arrow-down'):''}</button></th>`).join('')}<th class="mb-addcol">${btn(tr('显示列','Show columns'),'hide','plus')}</th></tr>`;}
 function groupsHTML(){const groups=grouped();return `<div class="mb-groups">${groups.map(g=>{const key='g_'+g.id,closed=view().collapsed.includes(key);return `<section class="mb-group" style="--group-color:${safeColor(g.color)}" data-mb-group-id="${esc(g.id)}"><header class="mb-group-head">${btn(word(g),'collapse-group',closed?'caret-right':'caret-down','',`data-key="${esc(key)}"`)}<span>${g.items.length} ${tr('项任务','tasks')}</span>${view().groupBy==='group'&&g.id!=='completed'&&ctx.actor?.role==='manager'?btn(tr('分组设置','Group options'),'edit-group','dots-three','mb-group-menu',`data-group="${esc(g.id)}"`):''}</header>${closed?'':`<div class="mb-table-scroll"><table class="mb-table" data-group="${esc(g.id)}"><thead>${head()}</thead><tbody>${g.items.map(t=>row(t,false,g.children)).join('')}<tr class="mb-add-row"><td></td><td colspan="${visibleCols().length+2}">${g.id==='completed'&&view().groupBy==='group'?`<span>${tr('Done 满 7 天后自动归入此组','Tasks enter this group 7 days after Done')}</span>`:`<button data-mb="new" data-group="${esc(view().groupBy==='group'?g.id:'todo')}">${ico('plus')} ${tr('添加任务','Add task')}</button>`}</td></tr></tbody><tfoot>${summary(g.items)}</tfoot></table></div>`}</section>`;}).join('')}${!data.items.length?`<div class="mb-empty"><h2>${tr('所有工作，从第一项任务开始。','Every project starts with a task.')}</h2><p>${tr('创建任务并设置负责人、优先级和截止日期。','Add a task, choose an owner, and set a priority and due date.')}</p>${btn(tr('新建任务','New task'),'new','plus','mb-new')}</div>`:''}${!groups.some(g=>g.items.length)&&data.items.length?`<p class="mb-empty">${tr('没有符合筛选条件的任务。','No tasks match your filters.')}</p>`:''}</div>`;}
 function row(t,sub,children=[]){const kids=sortTasks(children.filter(c=>c.parent_task_id===t.id)),open=expanded.has(t.id)||!!query||!!person||!!status;return `<tr class="mb-row ${selected.has(t.id)?'mb-selected':''}" data-task-id="${esc(t.id)}"><td class="mb-check"><input type="checkbox" data-mb-select="${esc(t.id)}" ${selected.has(t.id)?'checked':''} aria-label="${esc(tr('选择 ','Select ')+t.title)}"></td><td class="mb-task-cell"><div>${sub?'':btn('', 'expand',open?'caret-down':'caret-right','mb-expand',`data-id="${esc(t.id)}" aria-label="${tr('展开子任务','Expand subitems')}"`)}<button class="mb-title" data-mb="detail" data-id="${esc(t.id)}">${esc(t.title)}</button>${kids.length?`<small>${kids.length}</small>`:''}<button class="mb-comment" data-mb="detail" data-id="${esc(t.id)}" aria-label="${tr('任务详情与成果','Task details and evidence')}">${ico('chat-circle-dots')}</button>${btn('','task-menu','dots-three','mb-row-menu',`data-id="${esc(t.id)}" aria-label="${tr('任务选项','Task options')}"`)}</div></td>${visibleCols().map(([id])=>cell(t,id)).join('')}<td class="mb-addcol"></td></tr>${!sub&&open?`<tr class="mb-subitems"><td></td><td colspan="${visibleCols().length+2}"><table class="mb-table mb-subtable"><thead>${head(true)}</thead><tbody>${kids.map(c=>row(c,true)).join('')}<tr class="mb-add-row"><td></td><td colspan="${visibleCols().length+2}"><button data-mb="new" data-parent="${esc(t.id)}" data-group="${esc(t.board_group_id)}">${ico('plus')} ${tr('添加子任务','Add subitem')}</button></td></tr></tbody></table></td></tr>`:''}`;}
 function cell(t,k){let content='',style='',cls='';const value=t['board_'+k];if(['priority','status','category'].includes(k)){const l=label(k,value);style=`background:${safeColor(l?.color)};color:${k==='category'&&value==='marketing'?'#323338':'#fff'}`;content=l&&value!==''?word(l):'';cls='mb-color-cell';}else if(k==='owner')content=`<span class="mb-avatar">${esc(initials(t.owner_id))}</span><span class="mb-owner-name">${esc(name(t.owner_id))}</span>`;else if(k==='due'){const d=new Date(t.due_at),over=d.getTime()<Date.now()&&t.board_status!=='done';content=`${over?`<span class="mb-overdue">${ico('warning-circle')}</span>`:''}${new Intl.DateTimeFormat(ctx.language==='en'?'en-US':'zh-CN',{month:'short',day:'numeric'}).format(d)}`;}else if(k==='notes')content=esc(t.board_notes||'');else if(k==='updated'){const days=Math.floor((Date.now()-new Date(t.updated_at||t.created_at).getTime())/86400000);content=`<span class="mb-avatar">${esc(initials(t.updated_by||t.created_by))}</span><span>${days?days+' '+tr('天前','days ago'):tr('刚刚','Just now')}</span>`;}return `<td class="mb-col-${k} ${cls}" ${style?`style="${style}"`:''}><button data-mb="${k==='updated'?'detail':'edit-cell'}" data-id="${esc(t.id)}" data-field="${k}" aria-label="${esc(t.title+' · '+tr(...columns.find(c=>c[0]===k).slice(1)))}" title="${esc(k==='notes'?t.board_notes||tr('添加备注','Add notes'):k==='updated'?new Date(t.updated_at||t.created_at).toLocaleString():content.replace(/<[^>]+>/g,''))}">${content||'<span class="mb-blank">—</span>'}</button></td>`;}
 function summary(tasks){return `<tr class="mb-summary"><td></td><td></td>${visibleCols().map(([id])=>{if(['priority','status','category'].includes(id)){const parts=data.config[id].map(l=>({color:l.color,count:tasks.filter(t=>t['board_'+id]===l.id).length})).filter(p=>p.count);return `<td><div class="mb-summary-bar">${parts.map(p=>`<span style="background:${safeColor(p.color)};flex:${p.count}" title="${p.count}"></span>`).join('')}</div></td>`;}if(id==='due'){const dates=tasks.map(t=>new Date(t.due_at)).sort((a,b)=>a-b);return `<td><span class="mb-date-range">${dates.length?new Intl.DateTimeFormat(ctx.language==='en'?'en-US':'zh-CN',{month:'short',day:'numeric'}).format(dates[0]):'—'}</span></td>`;}return '<td></td>';}).join('')}<td></td></tr>`;}
 function footer(){return `<footer class="mb-footer"><span>${tr('Done 是执行状态；成果提交与人工验收仍单独记录。','Done tracks execution. Evidence submission and human acceptance remain separate.')}</span><span>${tr('满 7 天自动归入 Completed；重新打开会重置计时。','Done for 7 days → Completed. Reopening resets the clock.')}</span></footer>`;}
 function openMenu(kind,el,extra={}){const r=el.getBoundingClientRect();menu={kind,left:Math.max(10,Math.min(r.left,window.innerWidth-390)),top:Math.max(12,Math.min(r.bottom+7,window.innerHeight-440)),...extra};redraw();document.querySelector('.mb-popover input:not([type=checkbox]),.mb-popover select')?.focus();}
 function popover(){if(!menu)return '';let inner='';const m=menu,t=data.items.find(t=>t.id===m.id);const options=(values,action,current='')=>values.map(l=>btn(`${word(l)}${l.id===current?' '+tr('已选','Selected'):''}`,action,'','mb-label-option',`data-value="${esc(l.id)}" style="background:${safeColor(l.color)};color:${l.id==='marketing'?'#323338':'#fff'}"`)).join('');
  if(m.kind==='cell'&&['priority','status','category'].includes(m.field))inner=options(data.config[m.field],'pick-label',t?.['board_'+m.field])+(m.field==='category'?btn(tr('清除分类','Clear category'),'pick-label','','',`data-value=""`):'')+(ctx.actor.role==='manager'?btn(tr('编辑标签','Edit labels'),'labels','pencil-simple','',`data-field="${m.field}"`):'');
  if(m.kind==='person')inner=btn(tr('全部人员','All people'),'pick-person','','',`data-value=""`)+ctx.directory.map(u=>btn(esc(u.display_name),'pick-person','user-circle','',`data-value="${esc(u.id)}"`)).join('');
  if(m.kind==='filter')inner=btn(tr('全部状态','All statuses'),'pick-filter','','',`data-value=""`)+options(data.config.status,'pick-filter',status);
  if(m.kind==='groupBy')inner=[['group','原始分组','Original groups'],['priority','优先级','Priority'],['status','状态','Status'],['due','截止日期','Due date'],['category','分类','Category'],['owner','负责人','Owner']].map(([id,zh,en])=>btn(tr(zh,en),'pick-groupBy',view().groupBy===id?'check':'', '',`data-value="${id}"`)).join('');
  if(m.kind==='hide')inner=`<h3>${tr('显示的列','Visible columns')}</h3>`+columns.map(([id,zh,en])=>`<label class="mb-checkbox"><input type="checkbox" data-mb-column="${id}" ${view().hidden.includes(id)?'':'checked'}>${tr(zh,en)}</label>`).join('');
  if(m.kind==='sort')inner=`<h3>${tr('排序依据','Sort by')}</h3><div data-mb-sorts>${view().sort.map((s,i)=>`<div class="mb-sort-rule"><select data-mb-sort-field="${i}" aria-label="${tr('排序字段','Sort field')+' '+(i+1)}">${[['priority','优先级','Priority'],['due','截止日期','Due date'],['category','分类','Category'],['status','状态','Status'],['title','任务','Task'],['updated','最后更新','Last updated']].map(([id,zh,en])=>`<option value="${id}" ${s.field===id?'selected':''}>${tr(zh,en)}</option>`).join('')}</select><select data-mb-sort-direction="${i}" aria-label="${tr('排序方向','Sort direction')+' '+(i+1)}"><option value="asc" ${s.direction==='asc'?'selected':''}>${tr('升序','Ascending')}</option><option value="desc" ${s.direction==='desc'?'selected':''}>${tr('降序','Descending')}</option></select>${btn('','remove-sort','x','',`data-index="${i}" aria-label="${tr('删除排序','Remove sort')}"`)}</div>`).join('')}</div>${view().sort.length<5?btn(tr('新增排序','New sort'),'add-sort','plus'):''}`;
  if(m.kind==='task-menu')inner=btn(tr('查看详情与成果','Open details & evidence'),'detail','arrow-square-out','',`data-id="${esc(t?.id)}"`)+btn(tr('重命名','Rename'),'rename','pencil-simple','',`data-id="${esc(t?.id)}"`)+(t?.parent_task_id?'':btn(tr('添加子任务','Add subitem'),'new','plus','',`data-parent="${esc(t?.id)}" data-group="${esc(t?.board_group_id)}"`)+btn(tr('移至分组','Move to group'),'move','folder-simple','',`data-id="${esc(t?.id)}"`));
  if(m.kind==='move'||m.kind==='batch-group')inner=data.config.groups.filter(g=>g.id!=='completed').map(g=>btn(word(g),'pick-move','folder-simple','',`data-value="${esc(g.id)}"`)).join('');
  if(m.kind==='batch-status')inner=options(data.config.status,'pick-batch-status');
  if(m.kind==='cell'&&['notes','due','owner'].includes(m.field)||m.kind==='rename'){const f=m.kind==='rename'?'title':m.field;inner=`<form data-mb-cell-form><h3>${tr(f==='notes'?'备注':f==='due'?'截止日期':f==='owner'?'分派任务':'任务名称',f==='notes'?'Notes':f==='due'?'Due date':f==='owner'?'Assign task':'Task name')}</h3>${f==='notes'?`<textarea name="value" maxlength="10000" rows="6">${esc(t?.board_notes)}</textarea>`:f==='due'?`<input type="datetime-local" name="value" required value="${localDate(t?.due_at)}">`:f==='owner'?`<label>${tr('负责人','Owner')}<select name="ownerId">${ctx.directory.map(u=>`<option value="${esc(u.id)}" ${u.id===t?.owner_id?'selected':''}>${esc(u.display_name)}</option>`).join('')}</select></label><label>${tr('验收人','Reviewer')}<select name="reviewerId">${ctx.directory.filter(u=>u.role==='manager').map(u=>`<option value="${esc(u.id)}" ${u.id===t?.reviewer_id?'selected':''}>${esc(u.display_name)}</option>`).join('')}</select></label>`:`<input name="value" required minlength="3" maxlength="200" value="${esc(t?.title)}">`}<button class="mb-button mb-new" ${pending?'disabled':''}>${tr('保存','Save')}</button><p role="alert" data-mb-form-error></p></form>`;}
  if(['add-group','edit-group'].includes(m.kind))inner=`<form data-mb-group-form><h3>${tr('分组','Group')}</h3><label>${tr('英文名称','English name')}<input name="en" required maxlength="100" value="${esc(m.group?.en||'')}"></label><label>${tr('中文名称','Chinese name')}<input name="zh" required maxlength="100" value="${esc(m.group?.zh||'')}"></label><label>${tr('颜色','Color')}<input type="color" name="color" value="${safeColor(m.group?.color||'#ff007f')}"></label><button class="mb-button mb-new" ${pending?'disabled':''}>${tr('保存分组','Save group')}</button><p role="alert" data-mb-form-error></p></form>`;
  if(m.kind==='settings')inner=`<h3>${tr('看板设置','Board settings')}</h3>${['status','priority','category'].map(k=>btn(tr(k==='status'?'状态标签':k==='priority'?'优先级标签':'分类标签',k==='status'?'Status labels':k==='priority'?'Priority labels':'Category labels'),'labels','pencil-simple','',`data-field="${k}"`)).join('')}<p class="mb-help">${tr('Completed 是固定归档分组。Done 满 7 天且子任务均已满足条件时自动归档。','Completed is the fixed archive group. Tasks move after 7 full days in Done, once subitems also qualify.')}</p>`;
  if(m.kind==='labels')inner=`<form data-mb-label-form><h3>${tr('编辑标签','Edit labels')}</h3>${data.config[m.field].map((l,i)=>`<div class="mb-label-editor"><input aria-label="${tr('英文标签','English label')} ${i+1}" name="en-${i}" value="${esc(l.en)}" required maxlength="80"><input aria-label="${tr('中文标签','Chinese label')} ${i+1}" name="zh-${i}" value="${esc(l.zh)}" required maxlength="80"><input type="color" aria-label="${tr('标签颜色','Label color')} ${i+1}" name="color-${i}" value="${safeColor(l.color)}"></div>`).join('')}${m.field==='category'?`<label>${tr('新增分类（英文）','New category (English)')}<input name="newEn" maxlength="80"></label><label>${tr('新增分类（中文）','New category (Chinese)')}<input name="newZh" maxlength="80"></label>`:''}<button class="mb-button mb-new" ${pending?'disabled':''}>${tr('保存标签','Save labels')}</button><p role="alert" data-mb-form-error></p></form>`;
  return `<aside class="mb-popover ${m.kind==='sort'?'mb-sort-popover':''}" style="left:${m.left}px;top:${m.top}px" role="dialog" aria-label="${tr('看板菜单','Board menu')}"><button class="mb-pop-close" data-mb="close-menu" aria-label="${tr('关闭菜单','Close menu')}">${ico('x')}</button>${inner}${['sort','hide','groupBy'].includes(m.kind)?btn(tr('保存到此视图','Save to this view'),'save-view','floppy-disk','mb-save-view'):''}</aside>`;
 }
 function localDate(v){const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
 async function patch(t,values){const identityAtStart=identity,result=await ctx.api.post('/tasks/'+encodeURIComponent(t.id)+'/board',{expectedVersion:t.version,...values});if(identity!==identityAtStart)return;await refresh();return result;}
 async function shared(config){const before=identity;const result=await ctx.api.post('/task-board/config',{expectedVersion:data.version,...config});if(identity!==before)return;data.config=result.config;data.version=result.version;}
 async function saveView(){await ctx.api.post('/task-board/view',view());viewDirty=false;ctx.toast?.(tr('视图已保存','View saved'));}
 async function act(el){if(pending)return;const a=el.dataset.mb,t=data?.items.find(t=>t.id===el.dataset.id);if(a==='new'){menu=null;ctx.newTask?.({groupId:el.dataset.group||'todo',parentId:el.dataset.parent||null});return;}if(a==='detail'){menu=null;redraw();ctx.openTask?.(el.dataset.id);return;}
  if(a==='close-menu'){menu=null;redraw();return;}if(a==='expand'){expanded.has(t.id)?expanded.delete(t.id):expanded.add(t.id);redraw();return;}if(a==='collapse-group'){const k=el.dataset.key;view().collapsed=view().collapsed.includes(k)?view().collapsed.filter(x=>x!==k):[...view().collapsed,k];redraw();await saveView();return;}
  if(['person','filter','sort','hide','groupBy','settings','add-group','batch-status','batch-group','task-menu'].includes(a)){if(['settings','add-group'].includes(a)&&ctx.actor.role!=='manager'){ctx.toast?.(tr('分组与标签由负责人设置','A manager edits shared groups and labels'));return;}openMenu(a,el,{id:el.dataset.id});return;}
  if(a==='edit-cell'){if(el.dataset.field==='owner'&&ctx.actor.role!=='manager'){ctx.toast?.(tr('由负责人调整任务分派','Ask a manager to reassign tasks'));return;}openMenu('cell',el,{id:t.id,field:el.dataset.field});return;}
  if(['rename','move'].includes(a)){openMenu(a,el,{id:t.id});return;}if(a==='edit-group'){openMenu(a,el,{group:data.config.groups.find(g=>g.id===el.dataset.group)});return;}if(a==='labels'){if(ctx.actor.role!=='manager')return;openMenu(a,el,{field:el.dataset.field});return;}
  if(a==='clear-selection'){selected.clear();redraw();return;}
  if(a==='pick-person'){person=el.dataset.value;menu=null;redraw();return;}if(a==='pick-filter'){status=el.dataset.value;menu=null;redraw();return;}
  if(a==='pick-groupBy'){view().groupBy=el.dataset.value;viewDirty=true;menu=null;redraw();await saveView();return;}
  if(a==='column-sort'){const field=el.dataset.field;if(!['owner','notes'].includes(field)){const old=view().sort.find(s=>s.field===field);view().sort=[{field,direction:old?.direction==='asc'?'desc':'asc'}];viewDirty=true;redraw();}return;}
  if(a==='add-sort'){view().sort.push({field:'title',direction:'asc'});viewDirty=true;redraw();return;}if(a==='remove-sort'){view().sort.splice(Number(el.dataset.index),1);viewDirty=true;redraw();return;}
  if(a==='refresh'){pending=true;try{await refresh();menu=null;error='';}catch(e){error=e.message;}finally{pending=false;redraw();}return;}
  pending=true;try{if(a==='save-view'){await saveView();menu=null;}if(a==='pick-label'){const target=data.items.find(t=>t.id===menu.id);await patch(target,{[menu.field]:el.dataset.value});menu=null;}
   if(['pick-batch-status','pick-move'].includes(a)){const ids=menu.kind==='move'?[menu.id]:[...selected];if(a==='pick-move'&&ids.some(id=>{const t=data.items.find(t=>t.id===id);return t?.parent_task_id&&!ids.includes(t.parent_task_id);}))throw new Error(tr('请选中父任务，子任务会随父任务移动。','Select the parent task; its subitems move with it.'));for(const id of ids){const task=data.items.find(t=>t.id===id);if(a==='pick-move'&&task.parent_task_id)continue;await patch(task,{[a==='pick-move'?'groupId':'status']:el.dataset.value});}menu=null;selected.clear();}
  }catch(e){error=e.message;ctx.toast?.(e.message);}finally{pending=false;redraw();}
 }
 document.addEventListener('click',e=>{const el=e.target.closest?.('[data-mb]');if(el){void act(el).catch(err=>{error=err.message;redraw();});return;}if(menu&&!e.target.closest?.('.mb-popover')){menu=null;redraw();}});
 document.addEventListener('input',e=>{if(e.target.matches('[data-mb-search]')){query=e.target.value;redraw();}});
 document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-mb-select]')){el.checked?selected.add(el.dataset.mbSelect):selected.delete(el.dataset.mbSelect);redraw();}if(el.matches('[data-mb-select-group]')){const ids=[...el.closest('table').querySelectorAll(':scope > tbody > tr[data-task-id]')].map(r=>r.dataset.taskId);ids.forEach(id=>el.checked?selected.add(id):selected.delete(id));redraw();}if(el.matches('[data-mb-column]')){const col=el.dataset.mbColumn;view().hidden=el.checked?view().hidden.filter(x=>x!==col):[...view().hidden,col];viewDirty=true;redraw();}if(el.matches('[data-mb-sort-field]')){view().sort[Number(el.dataset.mbSortField)].field=el.value;viewDirty=true;}if(el.matches('[data-mb-sort-direction]')){view().sort[Number(el.dataset.mbSortDirection)].direction=el.value;viewDirty=true;}});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu){menu=null;redraw();}});
 document.addEventListener('submit',async e=>{const form=e.target;if(!form.matches('[data-mb-cell-form],[data-mb-group-form],[data-mb-label-form]'))return;e.preventDefault();if(pending)return;pending=true;const values=Object.fromEntries(new FormData(form)),active=menu;form.querySelector('button').disabled=true;try{
  if(form.matches('[data-mb-cell-form]')){const f=active.kind==='rename'?'title':active.field,t=data.items.find(t=>t.id===active.id);await patch(t,f==='owner'?{ownerId:values.ownerId,reviewerId:values.reviewerId}:{[f==='due'?'dueAt':f]:f==='due'?new Date(values.value).toISOString():values.value});}
  if(form.matches('[data-mb-group-form]')){const config=structuredClone(data.config),g={id:active.group?.id||crypto.randomUUID(),en:values.en.trim(),zh:values.zh.trim(),color:values.color};if(active.group)config.groups=config.groups.map(x=>x.id===g.id?g:x);else config.groups.splice(config.groups.length-1,0,g);await shared(config);}
  if(form.matches('[data-mb-label-form]')){const config=structuredClone(data.config);config[active.field]=config[active.field].map((l,i)=>({...l,en:values['en-'+i].trim(),zh:values['zh-'+i].trim(),color:values['color-'+i]}));if(active.field==='category'&&(values.newEn||values.newZh)){if(!values.newEn?.trim()||!values.newZh?.trim())throw new Error(tr('请填写分类的中英文名称','Enter both category names'));config.category.push({id:crypto.randomUUID(),en:values.newEn.trim(),zh:values.newZh.trim(),color:'#579bfc'});}await shared(config);}
  menu=null;ctx.toast?.(tr('已保存','Saved'));
 }catch(err){const target=form.querySelector('[data-mb-form-error]');if(target)target.textContent=err.message;else error=err.message;}finally{pending=false;if(menu===null)redraw();else if(document.contains(form))form.querySelector('button').disabled=false;}});
 function newTaskFields(context={}){if(!data)return '';return `<input type="hidden" name="boardGroupId" value="${esc(context.groupId||'todo')}">${context.parentId?`<input type="hidden" name="parentTaskId" value="${esc(context.parentId)}">`:''}<label class="field"><span>${tr('优先级','Priority')}</span><select name="boardPriority">${data.config.priority.map(l=>`<option value="${esc(l.id)}" ${l.id===''?'selected':''}>${word(l)}</option>`).join('')}</select></label><label class="field"><span>${tr('分类','Category')}</span><select name="boardCategory"><option value="">${tr('未分类','Uncategorized')}</option>${data.config.category.map(l=>`<option value="${esc(l.id)}">${word(l)}</option>`).join('')}</select></label>`;}
 setInterval(()=>{if(identity&&document.querySelector('[data-task-board-root]')&&!menu&&!pending&&!document.activeElement?.matches('input,textarea,select'))void refresh().then(redraw).catch(()=>{});},60000);
 return {configure,refresh,render,reset,newTaskFields,items:()=>data?.items||[],inspect:()=>({data,query,person,status})};
})();
